import type { Registry, RegistryComponent } from '@polymorph/registry'

import registryJson from '../../../registry/registry.json'

/**
 * The site's only content source: the registry, generated by `predev`/`prebuild`
 * from the publishing tree and never committed. TypeScript types the JSON import
 * structurally. The cast narrows it to the `Registry` interface, which the
 * generator validated against its own schema before writing.
 */
export const REGISTRY = registryJson as unknown as Registry

// Every tier the registry emits must be listed here. The Components index walks
// this array and calls `componentsByTier` only for the tiers in it. A tier
// missing from it leaves its members reachable by URL but listed nowhere, with
// no error.
export const TIERS = [
  'controls',
  'overlays',
  'structure',
  'layout',
  'charts',
  'ai',
  'archetypes',
  'icon',
] as const

export function componentsByTier(tier: string): RegistryComponent[] {
  return REGISTRY.components.filter((component) => component.tier === tier)
}

export function findComponent(name: string): RegistryComponent | undefined {
  return REGISTRY.components.find((component) => component.name === name)
}

export function componentSlug(name: string): string {
  return name.toLowerCase()
}

export function componentBySlug(slug: string): RegistryComponent | undefined {
  return REGISTRY.components.find((component) => component.name.toLowerCase() === slug)
}
